export const PAPERS: PaperInput[] = [
  {"id":"2609.35259","title":"On-Policy or Off-Policy Learning? A Systematic Study of Distillation Dynamics","up":175,"href":"https://arxiv.org/abs/2609.35259","abstract":"On-policy learning has been argued to reduce catastrophic forgetting, produce sparser parameter updates, and improve generalisation. However, existing comparisons between supervised fine-tuning and reinforcement learning vary many factors simultaneously, making the contribution of rollout policy difficult to isolate. We study the effect of rollout policy in a controlled strong-to-weak distillation setting, by independently varying rollout policy, token-level KL direction, and learning rate across the Llama3 and Qwen2.5 model families and reasoning tasks spanning scientific, medical, and arithm","crossrefDoi":"https://doi.org/10.1109/tnnls.2024.3373749/mm1"},
  {"id":"2610.01762","title":"OneStreamer: Unifying Perception, Memory, and Proactive Response in Streaming Video Interaction","up":168,"href":"https://arxiv.org/abs/2610.01762","abstract":"Streaming video LLMs must retain evidence before its relevance to future tasks is known and respond when sufficient evidence becomes available. The challenge is to form reusable factual memory without compromising real-time perception. We introduce OneStreamer, which jointly learns query-independent evidence recording and task response through a shared proactive generation process. Its Proactive Hierarchical Caption Memory (PHCM) produces time-grounded local-detail captions and summaries of completed events. Streaming caption targets supervise the interpretation of observed video prefixes duri","pdfUrl":"https://arxiv.org/pdf/2610.01762","primaryCategory":"cs.CV"},
  {"id":"2609.36585","title":"Transformers Stop Thinking Too Early, and a Tiny LoRA Fixes It","up":71,"href":"https://arxiv.org/abs/2609.36585","abstract":"Pretrained transformers use little of their depth to follow references in context. Thirteen base models reliably follow only 1.4-3.6 lines, and extra pretrained loops add little. A task-trained rank-8 LoRA at one early layer extends this computation with all model weights frozen. Qwen3-8B improves from 15.5% to 99% exact accuracy on 24-line chains; a longer-trained LoRA reaches 50 lines. Ouro-1.4B reaches 60 lines after four loops and at least 160 after eight. The LoRA starts a relay: program lines pass on their chain identity through a short range of middle layers. Frozen heads read progressi","pdfUrl":"https://arxiv.org/pdf/2609.36585","primaryCategory":"cs.AI"},
  {"id":"2609.32993","title":"X-Tree: Tokenizing Reusable Experience for Efficient Agent Generalization","up":62,"href":"https://arxiv.org/abs/2609.32993","abstract":"Multi-step agents are trained on flat action streams: SFT and RLVR weight every token uniformly and ignore the sub-procedures that recur across tasks, the hierarchy that lets humans plan top-down from reusable routines. This structure sits unused, and flat training uses each scarce trajectory less fully than its content allows. Recent agents do use that structure, but only as LLM-written skills in context, never in the weights, so their gains do not generalize beyond retrieval. We instead recover this hierarchy from the data itself and train on it, with no LLM calls. Following text tokenizers,"},
  {"id":"2609.37533","title":"E-MoE: Enhanced Mixture-of-Experts for Non-Factorized Diffusion Language Models","up":60,"href":"https://arxiv.org/abs/2609.37533","abstract":"Masked diffusion models (MDMs) generate sequences by progressively unmasking several tokens per denoising step, but their reverse process is typically factorized over positions, limiting sample quality in the few-step regime where diffusion's speed advantage over autoregressive decoding matters most. A recent line of work introduces a continuous Gaussian latent, trained as a variational autoencoder, to capture correlations across positions, but such approaches are prone to posterior collapse, where the latent is silently ignored. We propose Enhanced Mixture-of-Experts (E-MoE), which builds the","pdfUrl":"https://arxiv.org/pdf/2609.37533","primaryCategory":"cs.CL"},
  {"id":"2609.39378","title":"EgoTools: Towards Tool-Centric Reasoning in Real-World Egocentric Videos","up":57,"href":"https://arxiv.org/abs/2609.39378","abstract":"Real-world embodied tasks, from everyday activities to professional procedures, require agents to act under physical constraints while tracking evolving object and task states. Tool use sits at the heart of such tasks, as many everyday and professional activities are tool-mediated. Understanding them requires reasoning about affordances, hand-tool-object geometry, procedural progress, and causal effects on target objects. Yet despite strong performance on perception-oriented video tasks such as captioning and general video QA, current multimodal video models remain limited in this form of tool","pdfUrl":"https://arxiv.org/pdf/2609.39378","primaryCategory":"cs.CV"},
  {"id":"2610.00812","title":"Video Generation Models: A Survey of Post-Training and Alignment","up":55,"href":"https://arxiv.org/abs/2610.00812","abstract":"Video generation has rapidly progressed from short, low-quality clips to high-resolution, long-duration sequences with complex spatiotemporal dynamics. Despite strong generative priors learned through large-scale pretraining, pretrained video models often fail to reliably follow human intent, maintain temporal coherence, or satisfy physical and safety constraints. Compared with image and text generation, alignment in video generation presents unique challenges, including error accumulation over time, motion-appearance coupling, multi-objective trade-offs, and limited supervision for temporal p"},
  {"id":"2609.36388","title":"Persona Dosing: Calibrated Activation Steering for Graded Trait Control","up":48,"href":"https://arxiv.org/abs/2609.36388","abstract":"An activation-steering coefficient sets intervention strength, but requesting a particular degree of persona expression requires a behavioral scale. We study persona dosing: controlling a language model through a trait description and a requested mean intensity. PersonaDose specializes a shared, description-conditioned FLAS controller on persona responses, then calibrates its flow time against measured trait expression. Training responses are not paired with requested target intensities. Across Llama-3.1-8B, Qwen3-8B, and Gemma-3-4B, PersonaDose raises core-trait expression at the Persona Vect","pdfUrl":"https://arxiv.org/pdf/2609.36388","primaryCategory":"cs.AI"},
  {"id":"2610.01939","title":"Fewer Tokens, Better Action: GPT-6 Astra Robot Agents with 14% Higher Success Rate but 65% Fewer Tokens","up":45,"href":"https://arxiv.org/abs/2610.01939","abstract":"Vision language model (VLM) agents can control robots through visual feedback and action primitives, but repeated model invocations and redundant observations incur substantial token overhead. We introduce PyRUA-Lean, an interactive code-execution framework that couples feedback-driven primitive composition with selective observation: the agent composes classical robot primitives and learned vision-language-action (VLA) policies into Python cells that perform conditional checks and local retries, returning only explicitly requested images and state feedback for replanning. Across 700 simulated","pdfUrl":"https://arxiv.org/pdf/2610.01939","primaryCategory":"cs.CV"},
  {"id":"2606.10953","title":"Architect-Ant: Editable Automatic Furnishing of Architectural Floor Plans","up":43,"href":"https://arxiv.org/abs/2606.10953","abstract":"Furnished floor plans support real-estate visualization, interior design, and architectural workflows, yet automatic furnishing remains challenged by limited real-world data and the need to satisfy interacting geometric and functional constraints. We ask whether professional furnishing knowledge can be learned from real floor plans using a pretrained model, enabling direct constraint-aware layout generation without relying on costly iterative agentic inference. We introduce AntPlan, a curated dataset of 505 real professional architectural floor plans with dense furniture annotations spanning 9","pdfUrl":"https://arxiv.org/pdf/2606.10953","primaryCategory":"cs.AI"},
  {"id":"2610.02185","title":"Decoding Looped Transformers Better for (Almost) Free","up":41,"href":"https://arxiv.org/abs/2610.02185","abstract":"Looped Transformers achieve parameter efficiency by repeatedly executing a shared block across recurrent loops. Each loop yields an intermediate representation decodable for the same next token, yet standard decoding discards earlier states. Because earlier loops embody less computation, recurrence inherently supplies aligned weak-and-strong prediction pairs without auxiliary models or external training. We introduce LoopCD, a training-free contrastive decoding framework that guides token selection by contrasting the final prediction with an earlier recurrent pass, operating either in logit sp"},
  {"id":"2609.36820","title":"CorrGRPO: Correlation-Normalized GRPO for Multi-Reward Learning","up":30,"href":"https://arxiv.org/abs/2609.36820","abstract":"Group Relative Policy Optimization (GRPO) is widely used to train reasoning language models, where it computes advantages by centering and normalizing rewards across rollouts of the same prompt. For multiple rewards, GRPO sums the reward components and normalizes the total reward by its within-group standard deviation. The corresponding variance equals the sum of all pairwise reward covariances. For a fixed centered reward, larger aggregate covariance produces smaller advantages, and vice versa, allowing update magnitudes to adapt to reward dependence. However, correlated rewards with large sc","pdfUrl":"https://arxiv.org/pdf/2609.36820","primaryCategory":"cs.LG"},
  {"id":"2610.01092","title":"Ego2Act: Evaluating Goal-Directed Manipulation in Egocentric Video Generation","up":25,"href":"https://arxiv.org/abs/2610.01092","abstract":"Video generation models are increasingly being explored as world simulators for embodied planning and learning. To do so effectively, these models must not only generate visually appealing frames, but also predict how environments dynamically evolve when executing goal-directed actions. While evaluating these capabilities is crucial, existing benchmarks focus mainly on single short actions or step-by-step instructions. This leaves multi-step physical reasoning underexplored, especially in egocentric video generation that requires planning to simulate proper execution to accomplish high-level g","pdfUrl":"https://arxiv.org/pdf/2610.01092","primaryCategory":"cs.CV"},
  {"id":"2610.00559","title":"PhysVista: Benchmarking Physical Intelligence in VLMs via a Perception-Reasoning-Assessment Loop","up":23,"href":"https://arxiv.org/abs/2610.00559","abstract":"Vision-Language Models (VLMs) have shown strong multimodal reasoning capabilities, yet whether they truly capture the physical consistency underlying real-world dynamics remains unclear. Existing benchmark paradigms often suffer from fragmented evaluation, focusing on isolated cognitive stages while overlooking the inherent synergy between perception, reasoning, and physical judgment. The lack of a holistic perspective limits the ability to diagnose whether VLMs can reliably evaluate the physical authenticity of emerging generative models. To address these issues, we introduce PhysVista, a ben","pdfUrl":"https://arxiv.org/pdf/2610.00559","primaryCategory":"cs.CV"},
  {"id":"2610.02148","title":"Omni-Embed-Mini: Binding Modalities Without Forgetting via Dense Distillation","up":19,"href":"https://arxiv.org/abs/2610.02148","abstract":"Extending a text embedding model to new modalities typically degrades text retrieval quality, and existing omni-modal embedders compensate with multi-billion parameters. We present Omni-Embed-Mini, a 0.9B-parameter model that maps text, speech, audio, images, video, and visually-rich documents into a single shared cosine space without updating any text-side parameter. Our key insight is that the teacher signal requires no separate embedding model: each media sample is paired with a dense cascaded caption, and the teacher target is simply the frozen backbone's own embedding of that caption. Bec","pdfUrl":"https://arxiv.org/pdf/2610.02148","primaryCategory":"cs.CV"},
  {"id":"2610.02117","title":"Where-OPD: Spatially Guided On-Policy Self-Distillation of MLLMs with Synthetic Scenes","up":17,"href":"https://arxiv.org/abs/2610.02117","abstract":"On-policy self-distillation has recently emerged as an effective approach for improving language-model reasoning by supervising students with a frozen or EMA version of themselves that receives privileged information. Its application to multimodal large language models (MLLMs), however, remains largely unexplored. Recent approaches use privileged visual information, such as image crops corresponding to a question, to improve fine-grained perception, but their gains are confined to tasks that benefit from such visual zooming and require either human-annotated grounding data or external teacher "},
  {"id":"2609.32810","title":"OpenTumorBoard: A Real-World Benchmark of Multidisciplinary Tumor Board Discussion Trajectories","up":14,"href":"https://arxiv.org/abs/2609.32810","abstract":"Multidisciplinary tumor boards integrate multimodal clinical observations and longitudinal patient histories through specialist discussions, yet benchmarks rarely capture these real-world trajectories. We introduce OpenTumorBoard, a benchmark with 611 patient cases and 19,157 discussion turns across ten specialist roles, transcribed from 12,534 minutes of publicly available tumor board recordings on YouTube. The benchmark evaluates two settings: SPECIALIST TURN, in which an LLM responds to a clinically significant question posed during a real discussion, and BOARD SIMULATION, in which it gener"},
  {"id":"2610.00348","title":"Removing the NEEDLE in the Haystack: Backdoor Removal in LLMs via Weight Orthogonalisation","up":13,"href":"https://arxiv.org/abs/2610.00348","abstract":"Backdoor attacks can be implanted in Large Language Models (LLMs) during training, causing unwanted behaviour when a trigger appears in the input. Existing backdoor defences for LLMs attempt to remove the backdoor but inadvertently shift the model's output distribution to benign prompts, which can result in degraded model performance and safety. We propose NEEDLE, a training-free method for targeted backdoor removal. Once a trigger has been identified, our method estimates a backdoor direction and a refusal subspace through activation vectors, then applies sequential weight orthogonalisation t"},
  {"id":"2610.01108","title":"AgSpec: Pushing the Limits of Retrieval-Based Speculative Decoding in Coding Agent Pipelines","up":13,"href":"https://arxiv.org/abs/2610.01108","abstract":"Retrieval-based speculative decoding (SD) drafts tokens by copying continuations from existing text, which suits coding agents that repeatedly reproduce code, logs, and earlier attempts. Yet existing methods fall short in agent pipelines: much of the reusable text is missing from their corpora or stored in a form that differs from what the agent emits, and their draft lengths ignore that accept length varies across agents and drifts over turns. We present AgSpec, a framework that supplies the corpus and draft-length policies that existing retrieval engines lack in coding-agent pipelines. AgSpe"},
  {"id":"2609.34210","title":"RLE-Bench: A Qualifying Exam for Coding Agents as Robot Learning Engineers","up":12,"href":"https://arxiv.org/abs/2609.34210","abstract":"Coding agents are beginning to move beyond purely digital tasks to tackle physical-world challenges, particularly in robotics. Existing robotics benchmarks, however, primarily focus on the performance of individual artifacts, such as policies or controllers, offering limited coverage of coding agents' broader engineering capabilities. Real-world robotics extends beyond control: agents must build, integrate, diagnose, and improve heterogeneous artifacts under resource constraints and reason from multimodal feedback. To evaluate these broader capabilities, we introduce RLE-Bench, a benchmark of "},
  {"id":"2609.40222","title":"LOCI: Spatial Linear Memory for Streaming World Models","up":11,"href":"https://arxiv.org/abs/2609.40222","abstract":"When a camera revisits a previously observed region, a video world model should reproduce what was there before. This requires both remembering past observations and retrieving the right one for the current viewpoint. Key-value caches preserve visual detail but grow with video length; recurrent memory is compact but compresses history into a fixed-size state, so individual past observations are no longer directly accessible. We introduce LOCI, a hybrid spatial-memory architecture that keeps both representations. In half of the transformer blocks, main attention keeps a key-value cache of past "},
  {"id":"2610.00686","title":"SemanTok: Predictable Semantic Tokens for Efficient Autoregressive Video Generation","up":11,"href":"https://arxiv.org/abs/2610.00686","abstract":"Recent video-based world models pair the scalability of autoregressive (AR) prediction with the visual quality of diffusion models. The choice of scene tokenizer is paramount for the optimal performance of each of these, both in terms of fidelity and semantics. Flexible-length, coarse-to-fine tokenizers yield exactly that: the first coarse tokens carry the clip's global semantics while later tokens further specify details. Existing flexible tokenizers only apply a representation-alignment (REPA) loss on early decoder hidden states, a target the decoder can partly meet from its noised input ins"},
  {"id":"2610.01428","title":"Generalization Is Stability, Not Accuracy: Multi-Axis Evaluation of LLMs","up":11,"href":"https://arxiv.org/abs/2610.01428","abstract":"Generalization in large language models (LLMs) is the ability to produce consistent and semantically stable outputs when the same input is expressed in different ways. Existing work typically evaluates generalization through aggregate accuracy on a single prompt format, task, or set of variations, which conflates robustness with overall benchmark performance. In this work, we show generalization evaluation at the level of individual examples, across multiple input variants, and across different aspects of model behavior, focusing on variability rather than reducing performance to a score that "},
  {"id":"2610.01499","title":"VTR-Bench: A Systematic Benchmark for Evaluating Visual Text Rendering in Video Generation","up":11,"href":"https://arxiv.org/abs/2610.01499","abstract":"Recent video generation models can produce highly realistic videos from natural language instructions, with visual quality approaching cinematic standards. Existing evaluation benchmarks, however, predominantly assess visual quality, aesthetic appeal and physical plausibility, while paying limited attention to text, an essential medium for conveying information in everyday scenes. A generated video may appear visually compelling and feature lifelike subjects, yet still render the text within the scene incorrectly. To address this overlooked dimension, we introduce VTR-Bench, a systematic bench"},
];

